CREATE TYPE user_role AS ENUM ('USER','RJ','ADMIN');
CREATE TABLE profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, display_name text NOT NULL, role user_role NOT NULL DEFAULT 'USER', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE radio_stations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, azuracast_station_id text UNIQUE, public_stream_url text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE radio_shows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), station_id uuid REFERENCES radio_stations(id) ON DELETE CASCADE, title text NOT NULL, slug text UNIQUE NOT NULL, category text NOT NULL, description text NOT NULL DEFAULT '', artwork_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE show_hosts (show_id uuid REFERENCES radio_shows(id) ON DELETE CASCADE, profile_id uuid REFERENCES profiles(id) ON DELETE CASCADE, PRIMARY KEY(show_id,profile_id));
CREATE TABLE program_schedule (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), show_id uuid NOT NULL REFERENCES radio_shows(id) ON DELETE CASCADE, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, recurrence_rule text, CHECK(ends_at > starts_at), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE live_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), show_id uuid REFERENCES radio_shows(id), livekit_room text UNIQUE NOT NULL, state text NOT NULL CHECK(state IN ('scheduled','live','ended','failed')), started_at timestamptz, ended_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recordings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), show_id uuid REFERENCES radio_shows(id), title text NOT NULL, storage_path text NOT NULL, playback_url text, thumbnail_url text, duration_seconds integer CHECK(duration_seconds >= 0), started_at timestamptz, ended_at timestamptz, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE favorites (profile_id uuid REFERENCES profiles(id) ON DELETE CASCADE, show_id uuid REFERENCES radio_shows(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(profile_id,show_id));
CREATE TABLE listener_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid REFERENCES profiles(id) ON DELETE SET NULL, station_id uuid REFERENCES radio_stations(id), started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, seconds_listened integer NOT NULL DEFAULT 0 CHECK(seconds_listened >= 0));
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid REFERENCES profiles(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL, type text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_schedule_starts ON program_schedule(starts_at); CREATE INDEX ix_recordings_published ON recordings(published,created_at DESC); CREATE INDEX ix_listener_station ON listener_sessions(station_id,started_at DESC);
